typedef struct{float x,y;}MTPoint;typedef struct{MTPoint position,velocity;}MTVector;typedef struct{int frame;double timestamp;int identifier;int state;int fingerId;int handId;MTVector normalizedPosition;float total;float pressure;float angle;float majorAxis;float minorAxis;MTVector absolutePosition;int field14;int field15;float density;}MTTouch;typedef void*MTDeviceRef;typedef void(*MTFrameCallback)(MTDeviceRef,MTTouch[],int,double,int);
