static MTDeviceRef device;static RSTrackpadCallback receiver;static void frameCallback(MTDeviceRef unused,MTTouch touches[],int count,double timestamp,int frame){NSMutableArray*items=[NSMutableArray array];for(int i=0;i<count;i++){MTTouch t=touches[i];if(t.state<3||t.state>4)continue;[items addObject:@{@"id":@(t.identifier),@"x":@(t.normalizedPosition.position.x),@"y":@(t.normalizedPosition.position.y),@"pressure":@(t.pressure)}];}NSData*data=[NSJSONSerialization dataWithJSONObject:items options:0 error:nil];NSString*json=[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding];if(receiver&&json)receiver(json.UTF8String);}
void RSStartTrackpad(RSTrackpadCallback callback){receiver=callback;device=MTDeviceCreateDefault();if(!device)return;MTRegisterContactFrameCallback(device,frameCallback);MTDeviceStart(device,0);}void RSStopTrackpad(void){if(!device)return;MTDeviceStop(device);MTUnregisterContactFrameCallback(device,frameCallback);MTDeviceRelease(device);device=NULL;}
